discovery.query:
PREFIX agents: <https://data.oireachtas.ie/ontology#>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>
SELECT ?graph ?kind ?member ?name WHERE {
 { GRAPH ?graph { ?term a agents:DailTerm } BIND("dail_term_graph" AS ?kind) }
 UNION
 { GRAPH ?graph { ?member a agents:Member ; foaf:name ?name . FILTER(STR(?name) IN ("Micheál Martin", "Brendan Howlin", "Mary Lou McDonald")) } BIND("member_graph" AS ?kind) }
} GROUP BY ?graph ?kind ?member ?name ORDER BY ?kind ?graph ?member

direct_oracle.query:
PREFIX agents: <https://data.oireachtas.ie/ontology#>
PREFIX members: <https://data.oireachtas.ie/ontology/members#>
SELECT (COUNT(DISTINCT ?term) AS ?count) WHERE {
  GRAPH <https://data.oireachtas.ie/graph/member/Miche%C3%A1l-Martin.D.1989-06-29> {
    <https://data.oireachtas.ie/ie/oireachtas/member/id/Micheál-Martin.D.1989-06-29> a agents:Member ; members:hasMembersMembership ?membership .
    ?membership a members:DailMembership ; members:inHouseTerm ?term .
  }
  GRAPH <https://data.oireachtas.ie/graph/houses> { ?term a agents:DailTerm . }
}

